import json,os,stat,re,subprocess
from pathlib import Path
ac=Path('/var/lib/pink-iptv-acme030')
ng=Path('/etc/nginx/sites-available/pink-iptv-https.conf')
renew=Path('/etc/letsencrypt/renewal/pink-iptv.duckdns.org.conf')
needle='/var/lib/pink-iptv-acme030'
out={'operation':'pink_acme_webroot_preflight','read_only':True,'paths':{},'matches':{},'acme_tree':{},'nginx_check':False,'certbot_exists':False,'destination':{},'services':{}}
for tag,p in (('acme',ac),('nginx',ng),('renewal',renew)):
 out['paths'][tag]={'exists':p.exists(),'file':p.is_file(),'dir':p.is_dir(),'symlink':p.is_symlink()}
 if p.exists():
  st=p.stat();out['paths'][tag].update({'mode':oct(stat.S_IMODE(st.st_mode)),'uid':st.st_uid,'size':st.st_size})
 if p.is_file():
  t=p.read_text(errors='replace');m=[]
  for i,line in enumerate(t.splitlines(),1):
   if needle in line:
    m.append({'line':i,'text':line.strip()[:230]})
  out['matches'][tag]=m
if ac.is_dir() and not ac.is_symlink():
 out['acme_tree']['children']=[{'name':p.name,'kind':'dir' if p.is_dir() else 'file' if p.is_file() else 'link' if p.is_symlink() else 'other'} for p in ac.iterdir()]
 out['acme_tree']['depth_two_count']=sum(1 for d in ac.iterdir() if d.is_dir() for f in d.iterdir())
for path in ('/srv/projects/pink-iptv','/srv/projects/pink-iptv/www','/srv/projects/pink-iptv/private','/srv/projects/pink-iptv/archive'):
 p=Path(path);out['destination'][path]={'exists':p.exists(),'dir':p.is_dir(),'symlink':p.is_symlink()}
try:
 check=subprocess.run(['/usr/sbin/nginx','-t'],capture_output=True,timeout=10)
 out['nginx_check']=check.returncode==0
except Exception:pass
out['certbot_exists']=Path('/usr/bin/certbot').is_file()
for svc in ('nginx','pink-iptv-backend','pink-vpn'):
 out['services'][svc]=subprocess.run(['systemctl','is-active',svc],capture_output=True,text=True,timeout=8).stdout.strip()
print(json.dumps(out,separators=(',',':')))
